Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
    ];

    final newsItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);
    });

    Widget buildDashboard() => buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        );

    testWidgets('should show progress indicator while loading', (WidgetTester tester) async {
      await tester.pumpWidget(buildDashboard());

      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      await tester.pumpAndSettle();
    });

