import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/app/news_list/widgets/news_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
    ];

    final newsItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);
    });

    Widget buildDashboard() => buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        );

    testWidgets('should show progress indicator while loading', (WidgetTester tester) async {
      await tester.pumpWidget(buildDashboard());

      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      await tester.pumpAndSettle();
    });

    testWidgets('should load fresh currency rates and news feed in parallel', (WidgetTester tester) async {
      await tester.pumpWidget(buildDashboard());
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyCard), findsOneWidget);
      expect(find.byType(NewsCard), findsOneWidget);

      final CurrencyPageRequest request = verify(mockCurrencyRepository.fetchRates(captureAny)).captured.single as CurrencyPageRequest;
      expect(request.base, 'USD');

      final NewsFeedFilter filter = verify(mockNewsRepository.loadNewsFeed(captureAny)).captured.single as NewsFeedFilter;
      expect(filter.forceRefresh, isTrue);
    });
  });
}

